import net.runelite.http.api.worlds.WorldType;

import javax.inject.Inject;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;

@PluginDescriptor(
	name = "F2P Utilities",
	description = "Overlay members items with customizable visual effects (grayscale, outline, or fill)",
	tags = {"f2p", "members", "items", "overlay", "highlight", "grand exchange"}
)
@Slf4j
public class F2pPlugin extends Plugin
{
	private static final String EXCLUDED_ITEMS_KEY = "excludedItemIds";

	@Inject
	@Getter
	private Client client;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	@Inject
	@Getter
	private F2pConfig config;

	@Inject
	@Getter
	private ItemManager itemManager;

	@Provides
	F2pConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(F2pConfig.class);
	}

	@Inject
	private ClientThread clientThread;

	@Inject
	WorldService worldService;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private ItemOverlay overlay;

    @Inject
    private WorldMapOverlay worldMapOverlay;

	@Inject
	private KeyManager keyManager;

	private volatile boolean excludeKeyHeld = false;

	private final HotkeyListener excludeKeyListener = new HotkeyListener(() -> config.excludeKeybind())
	{
		@Override
		public void hotkeyPressed()
		{
			excludeKeyHeld = true;
		}

		@Override
		public void hotkeyReleased()
		{
			excludeKeyHeld = false;
		}
	};

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.LOGGING_IN) {
			overlay.invalidateAllCaches();
		}
	}

    @Override
    protected void startUp() {
        worldMapOverlay.loadPointsFromJson();
        overlayManager.add(overlay);
        overlayManager.add(worldMapOverlay);
        keyManager.registerKeyListener(excludeKeyListener);
    }

    @Override
    protected void shutDown() {
        keyManager.unregisterKeyListener(excludeKeyListener);
        excludeKeyHeld = false;
        overlayManager.remove(overlay);
        overlayManager.remove(worldMapOverlay);
        overlay.invalidateAllCaches();
        client.getItemCompositionCache().reset();
    }

	void saveExcludedItems(Set<Integer> itemIds) {
		if (itemIds == null || itemIds.isEmpty()) {
			configManager.unsetConfiguration(F2pConfig.GROUP, EXCLUDED_ITEMS_KEY);
			return;
		}
		String json = gson.toJson(List.copyOf(itemIds));
		configManager.setConfiguration(F2pConfig.GROUP, EXCLUDED_ITEMS_KEY, json);
	}

	public Set<Integer> getExcludedItemIds() {
		String json = configManager.getConfiguration(F2pConfig.GROUP, EXCLUDED_ITEMS_KEY);
		if (json == null || json.isBlank()) {
			return Collections.emptySet();
		}
		try {
			List<Integer> list = gson.fromJson(json, new TypeToken<List<Integer>>(){}.getType());
			return list != null ? new HashSet<>(list) : Collections.emptySet();
		} catch (Exception e) {
			log.warn("Failed to parse excluded items JSON", e);
			return Collections.emptySet();
		}
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event) {
		if (!isActive()) {
			return;
		}
		Keybind keybind = config.excludeKeybind();
		if (keybind == null || Keybind.NOT_SET.equals(keybind) || !excludeKeyHeld) {
			return;
		}
		MenuEntry entry = event.getMenuEntry();
		int itemId = getItemIdFromEntry(entry);
		if (itemId <= 0) {
			return;
		}
		boolean isMembers = client.getItemDefinition(itemId).isMembers();
		if (!isMembers) {
			return;
		}
		// Only add for Examine option to avoid duplicate entries per item
		if (!"Examine".equals(entry.getOption())) {
			return;
		}
		Set<Integer> excluded = getExcludedItemIds();
		boolean isExcluded = excluded.contains(itemId);
		MenuEntry parentEntry = client.createMenuEntry(-1)
			.setOption("F2P Utilities")
			.setTarget(entry.getTarget())
			.setType(MenuAction.RUNELITE);
		Menu submenu = parentEntry.createSubMenu();
		String subOption = isExcluded ? "Include in overlay" : "Exclude from overlay";
		submenu.createMenuEntry(-1)
			.setOption(subOption)
			.setType(MenuAction.RUNELITE)
			.onClick(e -> toggleExcludeItem(itemId));
	}

	private int getItemIdFromEntry(MenuEntry entry) {
		int itemId = entry.getItemId();
		if (itemId > 0) {
			return itemId;
		}
		if (entry.getWidget() != null && entry.getWidget().getItemId() > 0) {
			return entry.getWidget().getItemId();
		}
		return -1;
	}

	private void toggleExcludeItem(int itemId) {
		Set<Integer> excluded = new HashSet<>(getExcludedItemIds());
		if (excluded.contains(itemId)) {
			excluded.remove(itemId);
		} else {
			excluded.add(itemId);
		}
		saveExcludedItems(excluded);
		overlay.invalidateCache();
		clientThread.invokeLater(() -> client.getItemCompositionCache().reset());
	}

	@Subscribe
	public void onPostItemComposition(PostItemComposition event) {
		ItemComposition item = event.getItemComposition();
		if (item.isMembers() && config.icon() != -1 && shouldShowOverlayForItem(item.getId())) {
			event.getItemComposition().setName(formatName(event.getItemComposition().getName()));
		}
	}

	boolean shouldShowOverlayForItem(int itemId) {
		return isActive() && !overlay.isExcluded(itemId);
	}

    @Subscribe
    public void onWorldChanged(WorldChanged event) {
        try {
            if (client == null || worldService == null) {
                return;
            }
            overlay.invalidateAllCaches();
        } catch (Exception e) {
            log.warn("Error handling world change", e);
            overlay.invalidateAllCaches();
        }
    }

	private String formatName(String name) {
		return "<img=" + config.icon() + ">" + name;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{

		if (!event.getGroup().equals("f2p"))
		{
			return;
		}

		String key = event.getKey();

		switch (key) {
			case "overlayMode":
			case "overlayColor":
			case "overlayAlpha":
				overlay.invalidateCache();
				break;
			case "excludedItemIds":
				overlay.invalidateCache();
				clientThread.invokeLater(() -> client.getItemCompositionCache().reset());
				break;
			case "excludeKeybind":
				excludeKeyHeld = false;
				break;
		}

	}

	public boolean isActive() {
        ActiveType type = config.overlayActive();
		if (type == null) {
			return false;
		}

		if (type == ActiveType.ALWAYS) {
			return true;
		}

		if (type == ActiveType.NEVER) {
			return false;
		}

		if (type == ActiveType.FREE_WORLDS_ONLY) {
			try {
				if (client == null || worldService == null) {
					return false;
				}
				int world = client.getWorld();
				return !Objects.requireNonNull(worldService.getWorlds()).findWorld(world).getTypes().contains(WorldType.MEMBERS);
			} catch (Exception e) {
				return false;
			}
		}

		return false;
	}

}

package io.mark.f2p;

import com.google.common.cache.Cache;
import com.google.common.cache.CacheBuilder;
import com.google.inject.Inject;
import io.mark.f2p.config.OverlayMode;
import io.mark.f2p.overlay.CacheKey;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Point;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.concurrent.ExecutionException;

@Slf4j
public class ItemOverlay extends WidgetItemOverlay {

    private final ItemManager itemManager;
    private final F2pConfig config;
    private final F2pPlugin plugin;
    private final Cache<CacheKey, BufferedImage> imageCache;
    private final Cache<Integer, Boolean> membersCache;

    @Inject
    private ItemOverlay(ItemManager itemManager, F2pPlugin plugin, F2pConfig config) {
        this.itemManager = itemManager;
        this.config = config;
        this.plugin = plugin;
        this.imageCache = CacheBuilder.newBuilder()
                .maximumSize(1000)
                .build();
        this.membersCache = CacheBuilder.newBuilder()
                .maximumSize(1300)
                .build();

        showOnEquipment();
        showOnInventory();
        showOnBank();
    }



    @Override
    public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
    {
        if (!plugin.isActive()) {
            return;
        }
        if (!isMembers(itemId)) {
            return;
        }
        if (isExcluded(itemId)) {
            return;
        }

        OverlayMode mode = config.overlayMode();
        Rectangle bounds = widgetItem.getCanvasBounds();
        Color color = null;

        if (mode == OverlayMode.OUTLINE || mode == OverlayMode.FILL) {
            Color baseColor = config.overlayColor();
            int alpha = config.overlayAlpha();
            color = new Color(baseColor.getRed(), baseColor.getGreen(), baseColor.getBlue(), alpha);
        }

        try {
            BufferedImage cachedImage = getCachedImage(itemId, widgetItem.getQuantity(), mode, color);
            if (cachedImage != null) {
                graphics.drawImage(cachedImage, (int) bounds.getX(), (int) bounds.getY(), null);
            }
            int quantity = widgetItem.getQuantity();
            if (quantity > 1) {
                String quantityStr = formatQuantity(quantity);
                Color quantityColor = getQuantityColor(quantity);
                Point point = new Point((int) bounds.getX(), (int) bounds.getY() + 10);
                OverlayUtil.renderTextLocation(graphics, point, quantityStr, quantityColor);
            }
        } catch (ExecutionException e) {
            log.info("Unable to Render item: " + itemId);
        }
    }

    private String formatQuantity(int quantity) {
        if (quantity < 100_000) {
            return String.valueOf(quantity);
        }
        if (quantity < 10_000_000) {
            return quantity / 1000 + "K";
        }
        return quantity / 1_000_000 + "M";
    }

    private Color getQuantityColor(int quantity) {
        if (quantity < 100_000) {
            return Color.decode("#ffff00");
        }
        if (quantity < 10_000_000) {
            return Color.decode("#ffffff");
        }
        return Color.decode("#00ff80");
    }

    private boolean isMembers(int itemId) {
        try {
            return membersCache.get(itemId, () -> {
                try {
                    return itemManager.getItemComposition(itemId).isMembers();
                } catch (Exception e) {
                    log.warn("Error checking members status for item: " + itemId, e);
                    return false;
                }
            });
        } catch (ExecutionException e) {
            log.warn("Error getting members status from cache for item: " + itemId, e);
            return false;
        }
    }

    public boolean isExcluded(int itemId) {
        return plugin.getExcludedItemIds().contains(itemId);
    }

    private BufferedImage getCachedImage(int itemId, int quantity, OverlayMode mode, Color color) throws ExecutionException {
        CacheKey key = new CacheKey(itemId, quantity, mode, color);
        return imageCache.get(key, () -> {
            if (mode == OverlayMode.BLACK_AND_WHITE) {
                return createBlackAndWhiteImage(itemId, quantity);
            }
            else if (mode == OverlayMode.OUTLINE) {
                return itemManager.getItemOutline(itemId, quantity, color);
            }
            else if (mode == OverlayMode.FILL) {
                return createFillImage(itemId, quantity, color);
            }

            return null;
        });
    }

    private BufferedImage createBlackAndWhiteImage(int itemId, int quantity) {
        BufferedImage itemImage = itemManager.getImage(itemId, quantity, false);
        if (itemImage == null) {
            return null;
        }
        BufferedImage grayImage = new BufferedImage(itemImage.getWidth(), itemImage.getHeight(), BufferedImage.TYPE_INT_ARGB);
        Graphics2D g2d = grayImage.createGraphics();
        g2d.drawImage(itemImage, 0, 0, null);
        g2d.dispose();

        for (int y = 0; y < grayImage.getHeight(); y++) {
            for (int x = 0; x < grayImage.getWidth(); x++) {
                int rgb = grayImage.getRGB(x, y);
                int alpha = (rgb >> 24) & 0xFF;
                if (alpha > 0) {
                    int r = (rgb >> 16) & 0xFF;
                    int g = (rgb >> 8) & 0xFF;
                    int b = rgb & 0xFF;
                    int gray = (int) (0.299 * r + 0.587 * g + 0.114 * b);
                    grayImage.setRGB(x, y, (alpha << 24) | (gray << 16) | (gray << 8) | gray);
                }
            }
        }
        return grayImage;
    }

    private BufferedImage createFillImage(int itemId, int quantity, Color color) {
        BufferedImage itemImage = itemManager.getImage(itemId, quantity, false);
        if (itemImage == null) {
            return null;
        }
        BufferedImage filledImage = new BufferedImage(itemImage.getWidth(), itemImage.getHeight(), BufferedImage.TYPE_INT_ARGB);
        Graphics2D g2d = filledImage.createGraphics();
        g2d.drawImage(itemImage, 0, 0, null);
        g2d.setComposite(AlphaComposite.SrcAtop);
        g2d.setColor(color);
        g2d.fillRect(0, 0, itemImage.getWidth(), itemImage.getHeight());
        g2d.dispose();
        return filledImage;
    }


    public void invalidateCache() {
        imageCache.invalidateAll();
    }

    public void invalidateMembersCache() {
        membersCache.invalidateAll();
    }

    public void invalidateAllCaches() {
        imageCache.invalidateAll();
        membersCache.invalidateAll();
    }

}

package io.mark.f2p.overlay;

import io.mark.f2p.config.OverlayMode;

import java.awt.*;
import java.util.Objects;

public class CacheKey {
    private final int itemId;
    private final int quantity;
    private final OverlayMode mode;
    private final int colorHash;

    public CacheKey(int itemId, int quantity, OverlayMode mode, Color color) {
        this.itemId = itemId;
        this.quantity = quantity;
        this.mode = mode;
        this.colorHash = color != null ? color.hashCode() : 0;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        CacheKey cacheKey = (CacheKey) o;
        return itemId == cacheKey.itemId &&
                quantity == cacheKey.quantity &&
                colorHash == cacheKey.colorHash &&
                mode == cacheKey.mode;
    }

    @Override
    public int hashCode() {
        return Objects.hash(itemId, quantity, mode, colorHash);
    }
}

package io.mark.f2p.overlay;

import com.google.inject.Singleton;

